const r = $('Rank recipes').first().json;
const c = r.chosen || { missing: [] };
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const strip = s => String(s || "").replace(/[*_`#\[\]]/g, "").replace(/\s+/g, " ").trim();
const norm = s => strip(s).toLowerCase();
const clip = (s, max) => {
  s = strip(s);
  if (s.length <= max) return s;
  const first = s.match(/^.*?[.!?](\s|$)/);
  if (first && first[0].trim().length <= max) return first[0].trim();
  return s.slice(0, max).replace(/\s+\S*$/, "") + "...";
};
// substitutions only make sense when the user's pantry was compared to the recipe
const missingSet = r.mode === "ingredients" ? (c.missing || []).map(norm) : [];
const seen = new Set();
const subs = (Array.isArray(o.substitutions) ? o.substitutions : [])
  .filter(s => s && s.missing && s.replace_with
    && missingSet.includes(norm(s.missing))
    && norm(s.replace_with) !== norm(s.missing)
    && !missingSet.includes(norm(s.replace_with))
    && !seen.has(norm(s.missing)) && seen.add(norm(s.missing)))
  .slice(0, 3)
  .map(s => ({ missing: strip(s.missing), replace_with: strip(s.replace_with) }));
const chef = { intro: clip(o.intro, 220), tip: clip(o.tip, 200), substitutions: subs };
const validator_input = (r.chef_context || "") + "\n\nOutput to check:\n" + JSON.stringify(chef);
return [{ json: { chef, validator_input } }];

const r = $('Rank recipes').first().json;
const fa = $json;
const chef = $('Parse chef').first().json.chef;
const note = [chef.intro, chef.tip].filter(Boolean).join(" ");

// document mode: show the user's OWN parsed recipe
if (r.mode === "document" && r.parsed) {
  const p = r.parsed;
  return [{ json: {
    name: p.title || "Recipe from your image",
    minutes: null, kcal: null, protein_g: null, carbs_g: null, fat_g: null,
    ingredients: p.ingredients || [], steps: p.steps || [],
    cuisine_type: null, vegetarian: !!r.vegetarian,
    image_url: r.chosen && r.chosen.image_url ? r.chosen.image_url : null,
    chef_note: note, substitutions: fa.substitutions || [],
    kb_match: r.chosen ? r.chosen.name : null
  } }];
}

if (!fa.chosen) return [{ json: { error: fa.answer || "No matching recipe found." } }];

const c = r.chosen;
return [{ json: {
  name: c.name,
  minutes: c.minutes != null ? c.minutes : null,
  kcal: c.calories_per_serving != null ? c.calories_per_serving : null,
  protein_g: c.protein_g != null ? c.protein_g : null,
  carbs_g: c.carbs_g != null ? c.carbs_g : null,
  fat_g: c.fat_g != null ? c.fat_g : null,
  ingredients: (c.ingredient_lines && c.ingredient_lines.length)
    ? c.ingredient_lines : (c.needed || []).concat(c.pantry || []),
  steps: (c.steps || []).slice(0, 12),
  cuisine_type: c.cuisine_type || null,
  vegetarian: !!r.vegetarian,
  image_url: c.image_url || null,
  chef_note: note,
  substitutions: fa.substitutions || [],
  have: c.have || [], missing: c.missing || [], pantry: c.pantry || []
} }];
